update country_flag_history set label_fr = 'République restaurée (1867-1893)', label_en = 'Restored Republic (1867–1893)', notes_fr = 'Après la chute de Maximilien, Benito Juárez rétablit le drapeau républicain à l''aigle sans couronne.', notes_en = 'After Maximilian fell, Benito Juárez restored the republican flag with the uncrowned eagle.' where id = 2437 and iso_code = 'mx';
update country_flag_history set label_fr = 'Porfiriat (1893-1916)', label_en = 'Porfiriato (1893–1916)', notes_fr = 'Sous Porfirio Díaz, l''aigle est représenté de face, ailes déployées, dans un style néoclassique.', notes_en = 'Under Porfirio Díaz the eagle was shown facing forward with spread wings, in a neoclassical style.' where id = 2438 and iso_code = 'mx';
update country_flag_history set label_fr = 'États-Unis mexicains (1934-1968)', label_en = 'United Mexican States (1934–1968)', notes_fr = 'Le décret de 1934 uniformise le dessin de l''aigle ; il est remplacé en 1968 par la version de Francisco Eppens Helguera, toujours en usage.', notes_en = 'The 1934 decree standardised the eagle; it was replaced in 1968 by Francisco Eppens Helguera''s version, still in use.' where id = 2439 and iso_code = 'mx';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1823.png', '1823-04-14', '1864-04-10', 'Première République fédérale', 'First Federal Republic', 'Après l''abdication d''Iturbide, l''aigle perd sa couronne impériale et gagne un rameau de chêne et de laurier.', 'After Iturbide abdicated, the eagle lost its imperial crown and gained a branch of oak and laurel.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1864.png', '1864-04-10', '1867-06-19', 'Second Empire (Maximilien)', 'Second Empire (Maximilian)', 'L''empereur Maximilien de Habsbourg place l''aigle couronné au centre et des aigles impériaux aux quatre coins.', 'Emperor Maximilian of Habsburg placed the crowned eagle at the centre and imperial eagles in all four corners.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1916.svg', '1916-09-20', '1934-01-01', 'Révolution mexicaine (1916-1934)', 'Mexican Revolution (1916–1934)', 'Venustiano Carranza fait revenir l''aigle de profil dévorant le serpent, inspiré des codex aztèques.', 'Venustiano Carranza brought back the eagle in profile devouring the snake, inspired by Aztec codices.');
